package com.northstarbank.console.web;import com.northstarbank.console.service.FinancialService;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller public class ApprovalController{private final FinancialService service;public ApprovalController(FinancialService s){service=s;}@GetMapping("/approvals")String queue(Model m){m.addAttribute("requests",service.pending());return"approvals";}@PostMapping("/approvals/{id}/approve")String approve(@PathVariable String id){service.approve(id);return"redirect:/approvals?approved";}@PostMapping("/approvals/{id}/discard")String discard(@PathVariable String id){service.discard(id);return"redirect:/approvals?discarded";}}
